  const v: ReadSpan<f64> = readSpan(a, 0, 1);
  return v;
}
function mutate(a: f64[]): f64 {
  a.length = 0;
  return 1;
}
function run(a: f64[], b: f64[]): f64 {
  const w: ReadSpan<f64> = borrow(a);
  mutate(b);
  w[0];
  return 1;
}
export function entry(): f64 {
  return 1;
}

